xcluded.points, coins = excluded.coins, status = excluded.status, version = case when mission_templates.clues is distinct from excluded.clues or mission_templates.parts is distinct from excluded.parts then mission_templates.version + 1 else mission_templates.version end, updated_at = now(); alter table teams add column if not exists jump_at timestamptz; alter table teams add column if not exists land_at timestamptz; drop function if exists _defaults_v6(); alter function _defaults() rename to _defaults_v6; create function _defaults() returns jsonb language sql immutable as $$ select _defaults_v6() || jsonb_build_object( 'move_speed', 20, 'foot_speed', 13, 'fall_seconds', 18, 'glide_speed', 18) $$; create or replace function _br_roles_gate(p_arena uuid) returns boolean language plpgsql as $$ begin if (select phase from arenas where id = p_arena) <> 'play' then return false; end if; return _auto_roles(p_arena); end $$; create or replace function _jump_now(p_team uuid, p_xy float8[]) returns timestamptz language plpgsql as $$ declare t teams; v_land timestamptz; begin select * into t from teams where id = p_team for update; v_land := now() + _secs(_cfg(t.event_id, 'fall_seconds')); update teams set jump_at = now(), land_at = v_land, pos_x = p_xy[1], pos_y = p_xy[2], pos_at = now(), vel_x = 0, vel_y = 0, state = 'idle', travel_to = null, travel_arrive_at = null, vehicle = 'none', buggy_x = null, buggy_y = null, level = 0, bldg = null where id = p_team; perform _feed(t.arena_id, 'squad.jumped', jsonb_build_object('team', t.number)); perform _ping_team(p_team, 'move'); return v_land; end $$;
